11: export type StepResult =
12:   | {manager: UpdateManager; status: "updated" | "up-to-date"}
13:   | {manager: UpdateManager; status: "skipped" | "failed"; reason: string}
14:   | {manager: "local"; status: "unmanaged"}
15:   | {manager: "local"; status: "failed"; reason: string};
