22: export type UpdateDetector = (entry: ValidEntry) => Promise<UpdateStep[]>;
23: export type UpdateExecutor = (step: UpdateStep) => Promise<StepResult>;
24: 
25: function reason(error: unknown): string {
26:   return error instanceof Error ? error.message : String(error);
27: }
