29: export async function runUpdates(entries: readonly ValidEntry[], detect: UpdateDetector, execute: UpdateExecutor): Promise<EntryUpdateResult[]> {
30:   const cache = new Map<string, StepResult>();
31:   const results: EntryUpdateResult[] = [];
32:   for (const entry of entries) {
33:     let phases: UpdateStep[];
34:     try { phases = await detect(entry); }
35:     catch (cause) {
36:       results.push({entry, steps: [{manager: "local", status: "failed", reason: reason(cause)}]});
37:       continue;
38:     }
39:     if (!phases.length) {
40:       results.push({entry, steps: [{manager: "local", status: "unmanaged"}]});
41:       continue;
42:     }
43: 
44:     const steps: StepResult[] = [];
45:     let gitCompletedSafely = true;
46:     for (const phase of phases) {
47:       if (phase.manager === "npm" && !gitCompletedSafely) {
48:         steps.push({manager: "npm", status: "skipped", reason: "git phase did not complete safely"});
49:         continue;
50:       }
51:       let result = cache.get(phase.key);
52:       if (!result) {
53:         try { result = await execute(phase); }
54:         catch (cause) { result = {manager: phase.manager, status: "failed", reason: reason(cause)}; }
55:         cache.set(phase.key, result);
56:       }
57:       steps.push(result);
58:       if (phase.manager === "git") gitCompletedSafely = result.manager === "git" && (result.status === "updated" || result.status === "up-to-date");
59:     }
60:     results.push({entry, steps});
61:   }
62:   return results;
63: }

