32: export function createSystemUpdater(dependencies: SystemUpdaterDependencies): {detect: UpdateDetector; execute: UpdateExecutor} {
33:   const detect: UpdateDetector = async (entry: ValidEntry): Promise<UpdateStep[]> => {
34:     const phases: UpdateStep[] = [];
35:     const git = await dependencies.findExecutable("git");
36:     if (git) {
37:       const top = await dependencies.commandOutput(git, ["-C", entry.realPath, "rev-parse", "--show-toplevel"]).catch(() => ({code: 1, stdout: "", stderr: ""}));
38:       if (top.code === 0) {
39:         try {
40:           const root = await realpath(top.stdout.trim());
41:           if (root === entry.realPath) phases.push({manager: "git", key: `git:${root}`, cwd: root});
42:         } catch {
43:           // An unresolved reported root is not safe to update.
44:         }
45:       }
46:     } else if (await hasGitMarker(entry.realPath)) {
47:       phases.push({manager: "git", key: `git:${entry.realPath}`, cwd: entry.realPath});
48:     }
49:     if (await isRegularFile(path.join(entry.realPath, "package.json"))) {
50:       phases.push({manager: "npm", key: `npm:${entry.realPath}`, cwd: entry.realPath});
51:     }
52:     return phases;
53:   };
54: 
55:   const executeGit = async (step: UpdateStep): Promise<StepResult> => {
56:     const git = await dependencies.findExecutable("git");
57:     if (!git) return {manager: "git", status: "skipped", reason: "git not found"};
58:     const run = async (args: string[]) => dependencies.commandOutput(git, ["-C", step.cwd, ...args]);
59: 
60:     const status = await run(["status", "--porcelain"]);
61:     if (status.code !== 0) return {manager: "git", status: "failed", reason: commandFailure(status, "git status failed")};
62:     if (status.stdout.trim()) return {manager: "git", status: "skipped", reason: "dirty working tree"};
63:     const branch = await run(["symbolic-ref", "--quiet", "--short", "HEAD"]);
64:     if (branch.code !== 0) return {manager: "git", status: "skipped", reason: "detached HEAD"};
65:     const upstream = await run(["rev-parse", "--abbrev-ref", "@{upstream}"]);
66:     if (upstream.code !== 0) return {manager: "git", status: "skipped", reason: "missing upstream"};
67:     const before = await run(["rev-parse", "HEAD"]);
68:     if (before.code !== 0 || !before.stdout.trim()) return {manager: "git", status: "failed", reason: commandFailure(before, "could not read HEAD before update")};
69:     const pull = await run(["pull", "--ff-only"]);
70:     if (pull.code !== 0) return {manager: "git", status: "failed", reason: commandFailure(pull, "git pull failed")};
71:     const after = await run(["rev-parse", "HEAD"]);
72:     if (after.code !== 0 || !after.stdout.trim()) return {manager: "git", status: "failed", reason: commandFailure(after, "could not verify HEAD after update")};
73:     return {manager: "git", status: before.stdout.trim() === after.stdout.trim() ? "up-to-date" : "updated"};
74:   };
75: 
76:   const executeNpm = async (step: UpdateStep): Promise<StepResult> => {
77:     const npm = await dependencies.findExecutable("npm");
78:     if (!npm) return {manager: "npm", status: "skipped", reason: "npm not found"};
79:     if (!await isRegularFile(path.join(step.cwd, "package.json"))) return {manager: "npm", status: "failed", reason: "package.json is no longer a regular file"};
80:     const result = await dependencies.commandOutput(npm, ["update", "--json"], step.cwd);
81:     if (result.code !== 0) return {manager: "npm", status: "failed", reason: commandFailure(result, "npm update failed")};
82:     try {
83:       const parsed = JSON.parse(result.stdout) as {added?: unknown; removed?: unknown; changed?: unknown};
84:       const changed = [parsed.added, parsed.removed, parsed.changed].some((value) => typeof value === "number" && value > 0);
85:       return {manager: "npm", status: changed ? "updated" : "up-to-date"};
86:     } catch {
87:       return {manager: "npm", status: "updated"};
88:     }
89:   };
90: 
91:   const execute: UpdateExecutor = async (step) => step.manager === "git" ? executeGit(step) : executeNpm(step);
92:   return {detect, execute};
93: }
