57: export function naturalCompare(left: string, right: string): number {
58:   const leftRuns = runs(left);
59:   const rightRuns = runs(right);
60:   const length = Math.min(leftRuns.length, rightRuns.length);
61:   for (let index = 0; index < length; index += 1) {
62:     const a = leftRuns[index]!;
63:     const b = rightRuns[index]!;
64:     const digits = /^\d+$/.test(a) && /^\d+$/.test(b);
65:     if (digits) {
66:       const numberOrder = BigInt(a) < BigInt(b) ? -1 : BigInt(a) > BigInt(b) ? 1 : 0;
67:       if (numberOrder !== 0) return numberOrder;
68:     } else if (a !== b) {
69:       return a < b ? -1 : 1;
70:     }
71:   }
72:   if (leftRuns.length !== rightRuns.length) return leftRuns.length - rightRuns.length;
73:   return left < right ? -1 : left > right ? 1 : 0;
74: }

