20: export async function findExecutable(name: string, environment: NodeJS.ProcessEnv = process.env): Promise<string | undefined> {
21:   for (const directory of (environment.PATH ?? "").split(path.delimiter)) {
22:     if (!directory) continue;
23:     const candidate = path.resolve(directory, name);
24:     try { await access(candidate, constants.X_OK); return await realpath(candidate); } catch { /* continue */ }
25:   }
26:   return undefined;
