29: export async function commandOutput(command: string, args: string[], cwd?: string): Promise<{code: number; stdout: string; stderr: string}> {
30:   return await new Promise((resolve, reject) => {
31:     const child = spawn(command, args, {cwd, shell: false, stdio: ["ignore", "pipe", "pipe"]});
32:     let stdout = ""; let stderr = "";
33:     child.stdout.on("data", (data) => { stdout += data; }); child.stderr.on("data", (data) => { stderr += data; });
34:     child.on("error", reject); child.on("close", (code) => resolve({code: code ?? 1, stdout, stderr}));
35:   });
36: }
