38: export async function resolvePi(environment: NodeJS.ProcessEnv = process.env): Promise<{path: string; version: string}> {
39:   const executable = await findExecutable("pi", environment);
40:   if (!executable) throw new Error("PIW cannot launch because `pi` was not found on PATH");
41:   const result = await commandOutput(executable, ["--version"]);
42:   const version = semver.coerce(result.stdout.trim())?.version;
43:   if (result.code !== 0 || !version) throw new Error("PIW could not determine the installed Pi version");
44:   if (semver.lt(version, MINIMUM_PI_VERSION)) throw new Error(`PIW requires Pi >=${MINIMUM_PI_VERSION}; found ${version}`);
45:   return {path: executable, version};
46: }
